INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1700, 'crowdfunding', '/ˈkraʊdfʌndɪŋ/', 'noun', '{"zh-TW":["群眾募資"],"en":["raising small amounts of money from a large number of people online"]}', NULL, 'equity crowdfunding / crowdfunding platform / crowdfunding campaign', '[{"en":"The startup raised $1 million through a crowdfunding campaign.","zh-TW":"這家新創公司通過群眾募資籌集了100萬美元。"},{"en":"Crowdfunding democratizes access to startup investment.","zh-TW":"群眾募資使新創公司投資更加民主化。"}]', '{"verb":"crowdfund","noun":"crowdfunder"}', NULL, 4, 1700, NULL),
(1701, 'crowding out', '/ˈkraʊdɪŋ aʊt/', 'noun', '{"zh-TW":["排擠效應"],"en":["the phenomenon where increased government borrowing raises interest rates and reduces private investment"]}', NULL, 'risk of crowding out / crowding out effect / avoid crowding out', '[{"en":"Critics of deficit spending warn that crowding out reduces private sector investment.","zh-TW":"赤字支出的批評者警告，排擠效應減少了私人部門的投資。"},{"en":"Heavy government borrowing crowded out private firms from credit markets.","zh-TW":"大量政府借貸將私人企業從信貸市場中排擠出去。"}]', NULL, NULL, 4, 1701, NULL),
(1702, 'crucial', '/ˈkruːʃl/', 'adjective', '{"zh-TW":["關鍵的；至關重要的"],"en":["of great importance; critical","of great importance; decisive"]}', '{"root":{"text":"cruc","meaning":"cross (十字)"},"suffix":{"text":"-ial","meaning":"relating to (有關的)"},"logic":"在十字路口的（決定性的），即「關鍵的」。"}', 'crucial role/factor/decision; crucial role / crucial decision / crucial moment', '[{"en":"Timing is crucial for the success of this launch.","zh-TW":"時機對此次發布的成功至關重要。"},{"en":"Communication plays a crucial role in teamwork.","zh-TW":"溝通在團隊合作中扮演關鍵角色。"},{"en":"Teamwork is crucial to success.","zh-TW":"團隊合作對成功至關重要。"},{"en":"This is a crucial moment in the negotiations.","zh-TW":"這是談判中的關鍵時刻。"}]', '{"adverb":"crucially"}', NULL, 3, 1702, NULL),
(1703, 'cruel', '/ˈkruːəl/', 'adjective', '{"zh-TW":["殘忍的"],"en":["causing pain or suffering deliberately"]}', NULL, 'cruel treatment / cruel joke', '[{"en":"It''s cruel to hurt animals.","zh-TW":"傷害動物是殘忍的。"},{"en":"Don''t be so cruel.","zh-TW":"別這麼殘忍。"}]', '{"noun":"cruelty","adverb":"cruelly"}', NULL, 2, 1703, NULL),
(1704, 'cruise', '/kruːz/', 'noun', '{"zh-TW":["郵輪旅遊"],"en":["a vacation on a ship visiting several places"]}', NULL, 'take a cruise / luxury cruise', '[{"en":"They went on a Caribbean cruise for their anniversary.","zh-TW":"他們乘郵輪遊覽加勒比海慶祝周年紀念。"},{"en":"The cruise ship offers entertainment and fine dining.","zh-TW":"郵輪提供娛樂和精緻餐飲。"}]', '{"verb":"cruise","adjective":"cruising"}', NULL, 2, 1704, NULL),
(1705, 'cruise ship', '/''kruːz ʃɪp/', 'noun', '{"zh-TW":["遊輪"],"en":["a large ocean liner used for pleasure voyages where the ship itself is a significant part of the experience"]}', NULL, 'board a cruise ship / cruise ship itinerary / luxury cruise ship', '[{"en":"The cruise ship carried three thousand passengers and a crew of one thousand.","zh-TW":"這艘遊輪搭載了三千名旅客和一千名船員。"},{"en":"A Mediterranean cruise ship tour visited six countries in fourteen days.","zh-TW":"地中海遊輪行程在十四天內參觀了六個國家。"}]', NULL, NULL, 4, 1705, NULL),
(1706, 'crush', '/krʌʃ/', 'verb', '{"zh-TW":["壓碎；壓垮"],"en":["to press something so hard that it breaks"]}', NULL, 'crush ice / have a crush on', '[{"en":"Crush the garlic before adding it.","zh-TW":"加入前先壓碎大蒜。"},{"en":"She has a crush on her classmate.","zh-TW":"她暗戀她的同學。"}]', '{"noun":"crush"}', NULL, 2, 1706, NULL),
(1707, 'cry', '/kraɪ/', 'verb', '{"zh-TW":["哭；喊叫"],"en":["to produce tears","to shout","to produce tears from your eyes"]}', NULL, 'cry out / a far cry from; cry out / far cry', '[{"en":"This result is a far cry from what we expected.","zh-TW":"這個結果跟我們預期的相差甚遠。"},{"en":"She cried tears of joy.","zh-TW":"她喜極而泣。"},{"en":"The baby started to cry.","zh-TW":"寶寶開始哭了。"},{"en":"She cried out for help.","zh-TW":"她大聲呼救。"}]', '{"verb":"cry","noun":"cry"}', NULL, 1, 1707, NULL),
(1708, 'cryptographic hash', '/ˌkrɪptəˈɡræfɪk hæʃ/', 'noun', '{"zh-TW":["密碼學雜湊值"],"en":["a fixed-length output produced by a hash function from input data"]}', NULL, 'generate a cryptographic hash / verify cryptographic hash / SHA-256 cryptographic hash', '[{"en":"Cryptographic hashes verify data integrity in blockchain transactions.","zh-TW":"密碼學雜湊值驗證區塊鏈交易中的數據完整性。"},{"en":"Even a small change in input produces a completely different cryptographic hash.","zh-TW":"輸入中即使微小的變化也會產生完全不同的密碼學雜湊值。"}]', NULL, NULL, 5, 1708, NULL),
(1709, 'cryptography', '/krɪpˈtɒɡrəfi/', 'noun', '{"zh-TW":["密碼學"],"en":["the practice of securing communication by converting data into a coded form"]}', NULL, 'public-key cryptography / cryptography algorithm / apply cryptography', '[{"en":"Modern cryptography protects sensitive data in digital communications.","zh-TW":"現代密碼學保護數字通信中的敏感數據。"},{"en":"Quantum computing poses a long-term threat to current cryptography standards.","zh-TW":"量子計算對現有密碼學標準構成長期威脅。"}]', '{"adjective":"cryptographic","adverb":"cryptographically"}', NULL, 4, 1709, NULL),
(1710, 'CTO', '/ˌsiː tiː ˈoʊ/', 'noun', '{"zh-TW":["技術長；首席技術官"],"en":["chief technology officer; the executive leading technology strategy"]}', NULL, 'CTO responsibilities / appoint a CTO / CTO vision', '[{"en":"The CTO drove the company''s digital transformation initiative.","zh-TW":"技術長推動了公司的數位轉型計劃。"},{"en":"She joined as CTO to modernize the firm''s legacy IT infrastructure.","zh-TW":"她以技術長身份加入，以現代化公司的舊有IT基礎設施。"}]', '{"full form":"chief technology officer"}', NULL, 1, 1710, NULL),
(1711, 'cubicle', '/ˈkjuːbɪkəl/', 'noun', '{"zh-TW":["辦公隔間"],"en":["a small partitioned-off area in an open-plan office"]}', NULL, 'work in a cubicle / cubicle office layout', '[{"en":"She decorated her cubicle with photos and plants.","zh-TW":"她用照片和植物裝飾了她的辦公隔間。"},{"en":"Open offices replaced the traditional cubicle layout.","zh-TW":"開放式辦公室取代了傳統的隔間式佈局。"}]', NULL, NULL, 3, 1711, NULL),
(1712, 'cuisine', '/kwɪˈziːn/', 'noun', '{"zh-TW":["料理；烹飪風格"],"en":["a style or method of cooking"]}', NULL, 'Italian cuisine / local cuisine', '[{"en":"The restaurant specializes in Japanese cuisine.","zh-TW":"這家餐廳專門供應日本料理。"},{"en":"The hotel features restaurants offering five different cuisines.","zh-TW":"飯店設有提供五種不同料理的餐廳。"}]', '{"adjective":"culinary"}', NULL, 3, 1712, NULL),
(1713, 'culinary tourism', '/''kʌlɪnəri ˌtʊərɪzəm/', 'noun', '{"zh-TW":["美食旅遊"],"en":["travel motivated by the desire to experience local food and cuisine"]}', NULL, 'go on culinary tourism / culinary tourism destination / promote culinary tourism', '[{"en":"Culinary tourism is booming as food becomes a top reason to travel.","zh-TW":"隨著美食成為旅行的主要原因，美食旅遊正在蓬勃發展。"},{"en":"The city''s street food scene has made it a top culinary tourism destination.","zh-TW":"這座城市的街頭美食使其成為頂級美食旅遊目的地。"}]', NULL, NULL, 5, 1713, NULL),
(1714, 'culpability', '/ˌkʌlpəˈbɪlɪti/', 'noun', '{"zh-TW":["罪責；過失"],"en":["responsibility for a fault or wrong"]}', NULL, 'establish culpability / degree of culpability / criminal culpability', '[{"en":"The investigation examined the degree of culpability of each party.","zh-TW":"調查審查了各方的罪責程度。"},{"en":"Culpability may be reduced if the defendant lacked criminal intent.","zh-TW":"如果被告缺乏犯罪意圖，罪責可能會降低。"}]', '{"adjective":"culpable","adverb":"culpably"}', NULL, 4, 1714, NULL),
(1715, 'culpable', '/ˈkʌlpəbəl/', 'adjective', '{"zh-TW":["有罪的；應受責備的"],"en":["responsible for a fault or wrong; deserving blame"]}', NULL, 'culpable negligence / found culpable / morally culpable', '[{"en":"The investigation found both parties culpable for the accident.","zh-TW":"調查發現雙方均對事故負有責任。"},{"en":"Culpable negligence in medical practice can result in loss of license.","zh-TW":"醫療實踐中的應受責備的疏失可能導致執照被吊銷。"}]', '{"noun":"culpability","adverb":"culpably"}', NULL, 3, 1715, NULL),
(1716, 'cult following', '/kʌlt ˈfɒləʊɪŋ/', 'noun', '{"zh-TW":["死忠粉絲群；狂熱追隨者群"],"en":["a group of devoted fans of an obscure or unusual cultural work"]}', NULL, 'develop a cult following / gain a cult following / cult following of a film', '[{"en":"The low-budget horror film developed a massive cult following over decades.","zh-TW":"這部低成本恐怖片幾十年來發展出了龐大的狂熱追隨者群。"},{"en":"The band never achieved mainstream success but earned a devoted cult following.","zh-TW":"這個樂隊從未獲得主流成功，但贏得了忠實的死忠粉絲群。"}]', NULL, NULL, 5, 1716, NULL),
(1717, 'cultivate', '/ˈkʌltɪveɪt/', 'verb', '{"zh-TW":["培養；培育","培養；耕種"],"en":["to develop or improve by education or training","to grow plants","to develop a quality or skill"]}', '{"root":{"text":"cult","meaning":"tend/grow (耕種)"},"suffix":{"text":"-ivate","meaning":"to make (使)"},"logic":"使耕種成長，即「培養」。"}', 'cultivate relationships/skills/talent; cultivate relationships / cultivate land', '[{"en":"We cultivate long-term relationships with our partners.","zh-TW":"我們培養與合作夥伴的長期關係。"},{"en":"The program helps cultivate future leaders.","zh-TW":"該計畫幫助培養未來的領導者。"},{"en":"Farmers cultivate rice in this region.","zh-TW":"農民在這個地區種植稻米。"},{"en":"She cultivated strong relationships with clients.","zh-TW":"她培養了與客戶的良好關係。"}]', '{"noun":"cultivation"}', NULL, 3, 1717, 664),
(1718, 'cultural', '/ˈkʌltʃərəl/', 'adjective', '{"zh-TW":["文化的"],"en":["relating to the ideas and customs of a society"]}', NULL, 'cultural difference / cultural exchange', '[{"en":"There are cultural differences between countries.","zh-TW":"國家之間存在文化差異。"},{"en":"The city offers many cultural activities.","zh-TW":"這座城市提供許多文化活動。"}]', '{"noun":"culture","adverb":"culturally"}', NULL, 3, 1718, NULL),
(1719, 'cultural appropriation', '/ˈkʌltʃərəl əˌprəʊpriˈeɪʃən/', 'noun', '{"zh-TW":["文化挪用"],"en":["the adoption of cultural elements by members of another culture without understanding"]}', NULL, 'accused of cultural appropriation / cultural appropriation debate / cultural appropriation controversy', '[{"en":"The costume was criticized as cultural appropriation of indigenous traditions.","zh-TW":"這套服裝因挪用原住民傳統而受到批評。"},{"en":"The debate around cultural appropriation raises important questions about respect.","zh-TW":"圍繞文化挪用的辯論提出了關於尊重的重要問題。"}]', NULL, NULL, 5, 1719, NULL),
(1720, 'cultural capital', '/ˈkʌltʃərəl ˈkæpɪtəl/', 'noun', '{"zh-TW":["文化資本"],"en":["non-financial social assets promoting social mobility"]}', NULL, 'accumulate cultural capital / lack cultural capital / cultural capital theory', '[{"en":"Bourdieu''s cultural capital theory explains how education reproduces social inequality.","zh-TW":"布迪厄的文化資本理論解釋了教育如何再現社會不平等。"},{"en":"Access to museums and cultural institutions builds children''s cultural capital.","zh-TW":"進入博物館和文化機構培養了孩子的文化資本。"}]', NULL, NULL, 5, 1720, NULL),
(1721, 'cultural festival', '/''kʌltʃərəl ˌfestɪvəl/', 'noun', '{"zh-TW":["文化節；文化慶典"],"en":["a celebration that showcases a community''s cultural traditions, arts, and music"]}', NULL, 'attend a cultural festival / cultural festival performance / annual cultural festival', '[{"en":"The cultural festival drew visitors from all over the country to experience local traditions.","zh-TW":"文化節吸引了來自全國各地的遊客體驗當地傳統。"},{"en":"She attended the cultural festival and participated in traditional dance workshops.","zh-TW":"她參加了文化節，並參與了傳統舞蹈工作坊。"}]', NULL, NULL, 5, 1721, NULL),
(1722, 'cultural heritage', '/''kʌltʃərəl ˈherɪtɪdʒ/', 'noun', '{"zh-TW":["文化遺產"],"en":["the legacy of physical artifacts and intangible attributes inherited from past generations"]}', NULL, 'preserve cultural heritage / UNESCO cultural heritage / celebrate cultural heritage', '[{"en":"The city''s cultural heritage includes centuries-old architecture and traditions.","zh-TW":"這座城市的文化遺產包括幾個世紀以前的建築和傳統。"},{"en":"Protecting cultural heritage sites from tourism damage is a global priority.","zh-TW":"保護文化遺產地免受旅遊業破壞是全球優先事項。"}]', NULL, NULL, 5, 1722, NULL),
(1723, 'cultural immersion', '/''kʌltʃərəl ɪˈmɜːʃən/', 'noun', '{"zh-TW":["文化沉浸；文化融入"],"en":["the practice of fully engaging with a foreign culture during travel"]}', NULL, 'cultural immersion program / deep cultural immersion / pursue cultural immersion', '[{"en":"Living with a local family provided true cultural immersion.","zh-TW":"與當地家庭同住提供了真正的文化沉浸體驗。"},{"en":"Cultural immersion travel goes beyond sightseeing to connect with local life.","zh-TW":"文化沉浸旅行超越了觀光，與當地生活相連接。"}]', NULL, NULL, 5, 1723, NULL),
(1724, 'culture', 'ˈkʌltʃər', 'noun', '{"zh-TW":["文化；企業文化","培養"],"en":["the customs of a group","the beliefs and practices of a company"]}', NULL, 'company culture/cultural diversity', '[{"en":"Our company culture values teamwork.","zh-TW":"我們的公司文化重視團隊合作。"}]', '{"adjective":"cultural","adverb":"culturally"}', NULL, 3, 1724, NULL),
(1725, 'cumbersome', '/''kʌmbərsəm/', 'adjective', '{"zh-TW":["笨重的；繁瑣的"],"en":["large or heavy and therefore difficult to carry; slow and complicated"]}', NULL, 'cumbersome process / cumbersome system / cumbersome procedure', '[{"en":"The approval process was so cumbersome that it delayed project timelines significantly.","zh-TW":"審批流程如此繁瑣，以至於顯著延遲了項目時間表。"},{"en":"The new software replaced the old cumbersome paper-based reporting system.","zh-TW":"新軟體替換了舊的笨重紙質報告系統。"}]', '{"adverb":"cumbersomely","noun":"cumbersomeness"}', NULL, 4, 1725, NULL),
(1726, 'cup', '/kʌp/', 'noun', '{"zh-TW":["杯子"],"en":["a small container for drinking"]}', NULL, 'cup of tea / World Cup', '[{"en":"Would you like a cup of tea?","zh-TW":"你想來杯茶嗎？"},{"en":"The World Cup is held every four years.","zh-TW":"世界盃每四年舉行一次。"}]', NULL, NULL, 1, 1726, NULL),
(1727, 'curation', '/kjʊˈreɪʃən/', 'noun', '{"zh-TW":["策展；精選整理"],"en":["the action of selecting, organizing, and presenting content or a collection"]}', NULL, 'content curation / data curation / careful curation', '[{"en":"Content curation helps audiences navigate an overwhelming amount of information.","zh-TW":"內容策展幫助受眾瀏覽大量資訊。"},{"en":"The algorithm''s curation of news feeds has been controversial.","zh-TW":"算法對新聞訂閱的策展一直存在爭議。"}]', '{"verb":"curate","noun2":"curator"}', NULL, 3, 1727, NULL),
(1728, 'curator', '/kjʊˈreɪtər/', 'noun', '{"zh-TW":["策展人；館長"],"en":["a person in charge of a museum or gallery collection"]}', '{"root":{"text":"cur","meaning":"care (照料)"},"suffix":{"text":"-ator","meaning":"person who (…的人)"},"logic":"照料收藏品的人，即「策展人」。"}', 'museum curator / guest curator', '[{"en":"The curator organized a new exhibition.","zh-TW":"策展人組織了一場新展覽。"},{"en":"She works as a curator at the national museum.","zh-TW":"她在國家博物館擔任策展人。"}]', '{"verb":"curate","noun":"curation"}', NULL, 3, 1728, NULL),
(1729, 'curb', '/kɜːrb/', 'verb', '{"zh-TW":["抑制；控制"],"en":["to restrain or keep in check"]}', '{"root":{"text":"curb","meaning":"curve/bend (彎曲)"},"logic":"彎曲拉回，即「抑制」。"}', 'curb spending/inflation/emissions', '[{"en":"The government introduced measures to curb inflation.","zh-TW":"政府推出了抑制通膨的措施。"},{"en":"We need to curb unnecessary spending.","zh-TW":"我們需要控制不必要的支出。"}]', NULL, NULL, 1, 1729, NULL),
(1730, 'curbside appeal', '/''kɜːrbˌsaɪd əˌpiːl/', 'noun', '{"zh-TW":["外觀吸引力；門面整潔度"],"en":["the attractiveness of a property as seen from the street, which can significantly affect sale price"]}', NULL, 'improve curbside appeal / enhance curbside appeal / lack of curbside appeal', '[{"en":"Fresh paint and a tidy garden dramatically improved the home''s curbside appeal.","zh-TW":"新油漆和整潔的花園顯著提升了房屋的外觀吸引力。"},{"en":"Real estate agents emphasize curbside appeal to attract more potential buyers.","zh-TW":"房地產經紀人強調外觀吸引力，以吸引更多潛在買家。"}]', NULL, NULL, 5, 1730, NULL),
(1731, 'cure', '/kjʊr/', 'noun', '{"zh-TW":["治療；療法"],"en":["a treatment that makes someone well"]}', NULL, 'cure for / no cure', '[{"en":"There is no cure for this disease yet.","zh-TW":"這種疾病目前還沒有治療方法。"},{"en":"Prevention is better than cure.","zh-TW":"預防勝於治療。"}]', '{"verb":"cure","adjective":"curable"}', NULL, 1, 1731, NULL),
(1732, 'curious', '/ˈkjʊriəs/', 'adjective', '{"zh-TW":["好奇的"],"en":["wanting to know or learn something","eager to know or learn something"]}', '{"root":{"text":"cur","meaning":"care (關心)"},"suffix":{"text":"-ious","meaning":"full of (充滿)"},"logic":"充滿關心想了解的，即「好奇的」。"}', 'curious about / curious mind', '[{"en":"Children are naturally curious.","zh-TW":"孩子們天生好奇。"},{"en":"I''m curious about your trip.","zh-TW":"我很好奇你的旅行。"},{"en":"Children are naturally curious about the world.","zh-TW":"孩子天生對世界充滿好奇。"},{"en":"I''m curious to know what happened.","zh-TW":"我很好奇發生了什麼事。"}]', '{"noun":"curiosity","adverb":"curiously"}', NULL, 3, 1732, NULL),
(1733, 'currency', '/ˈkʌrənsi/', 'noun', '{"zh-TW":["貨幣；通貨"],"en":["a system of money in general use"]}', '{"root":{"text":"curr","meaning":"run (流通)"},"suffix":{"text":"-ency","meaning":"state (狀態)"},"logic":"流通的狀態，即「貨幣」。"}', 'foreign currency / currency exchange / digital currency', '[{"en":"Please specify payment in local currency.","zh-TW":"請以當地貨幣指定付款。"},{"en":"Currency exchange rates fluctuate daily.","zh-TW":"匯率每天波動。"}]', NULL, NULL, 3, 1733, 850),
(1734, 'currency exchange', '/ˈkʌrənsi ɪksˈtʃeɪndʒ/', 'noun', '{"zh-TW":["貨幣兌換；外匯兌換"],"en":["the process of converting one currency to another"]}', NULL, 'currency exchange rate / currency exchange service', '[{"en":"Look for the best currency exchange rate before traveling.","zh-TW":"出行前尋找最佳的貨幣兌換匯率。"},{"en":"Currency exchange services are available at most airports.","zh-TW":"大多數機場都有貨幣兌換服務。"}]', NULL, NULL, 5, 1734, NULL),
(1735, 'currency exchange rate', '/''kʌrənsi ɪksˌtʃeɪndʒ reɪt/', 'noun', '{"zh-TW":["貨幣匯率；外匯匯率"],"en":["the rate at which one currency can be exchanged for another"]}', NULL, 'monitor the currency exchange rate / favorable currency exchange rate / currency exchange rate fluctuation', '[{"en":"She checked the currency exchange rate before deciding when to convert her savings.","zh-TW":"她在決定何時兌換存款之前查看了貨幣匯率。"},{"en":"A favorable currency exchange rate makes traveling abroad more affordable.","zh-TW":"有利的貨幣匯率使海外旅行更加實惠。"}]', '{"noun":"exchange rate"}', NULL, 5, 1735, NULL),
(1736, 'currency hedging', '/ˈkʌrənsi ˈhedʒɪŋ/', 'noun', '{"zh-TW":["貨幣對沖"],"en":["using financial instruments to reduce exposure to exchange rate risk"]}', NULL, 'use currency hedging / currency hedging strategy', '[{"en":"The company uses currency hedging to protect overseas earnings.","zh-TW":"公司使用貨幣對沖保護海外收益。"},{"en":"Currency hedging is essential for firms with significant foreign revenues.","zh-TW":"對於擁有大量外幣收入的公司，貨幣對沖至關重要。"}]', '{"verb":"hedge currency","noun":"currency hedge"}', NULL, 5, 1736, NULL),
(1737, 'current', '/ˈkʌrənt/', 'adjective', '{"zh-TW":["【主要意義-形容詞】現在的；當前的","【次要意義-名詞】水流；氣流；洋流","【次要意義-名詞】電流","【次要意義-名詞】潮流；趨勢"],"en":["[primary - adjective] happening or existing at the present time","[secondary - noun] a steady flow of water, air, or electricity","[secondary - noun] the general trend or direction of events"]}', '{"root":{"text":"curr","meaning":"run (流動)"},"suffix":{"text":"-ent","meaning":"being (存在的)"},"logic":"正在流動存在的，即「目前的」。"}', 'current account / current affairs / alternating current / against the current', '[{"en":"The current account shows a surplus for the third consecutive quarter.","zh-TW":"往來帳戶連續第三季顯示盈餘。"},{"en":"Swimming against the current requires twice as much effort.","zh-TW":"逆流而游需要付出兩倍的努力。"},{"en":"The company must adapt to current trends in digital marketing.","zh-TW":"公司必須適應數位行銷的當前趨勢。"}]', '{"adverb":"currently","noun":"currency"}', 'current account（往來帳戶）是 TOEIC 銀行業文章必考詞，current 作名詞表「電流/水流/趨勢」，currency（貨幣）源於同一詞根，這些用法容易被忽略。', 3, 1737, NULL),
(1738, 'current account', '/ˈkɜːrənt əˈkaʊnt/', 'noun', '{"zh-TW":["往來帳戶；活期帳戶"],"en":["a bank account used for regular transactions; also the balance of trade in goods"]}', NULL, 'open a current account / current account deficit', '[{"en":"The company holds most operating funds in a current account.","zh-TW":"公司在往來帳戶中持有大部分運營資金。"},{"en":"A current account deficit means a country imports more than it exports.","zh-TW":"往來帳戶逆差意味著一個國家的進口多於出口。"}]', NULL, NULL, 5, 1738, NULL),
(1739, 'current assets', '/ˈkʌrənt ˈæsets/', 'noun', '{"zh-TW":["流動資產"],"en":["assets expected to be converted to cash within one year"]}', NULL, 'manage current assets / current assets ratio / increase current assets', '[{"en":"Cash and inventory are the main current assets on the balance sheet.","zh-TW":"現金和庫存是資產負債表上的主要流動資產。"},{"en":"High current assets indicate strong short-term liquidity.","zh-TW":"高流動資產表明強勁的短期流動性。"}]', NULL, NULL, 5, 1739, NULL),
(1740, 'current liabilities', '/ˈkʌrənt ˌlaɪəˈbɪlɪtɪz/', 'noun', '{"zh-TW":["流動負債"],"en":["obligations due within one year"]}', NULL, 'pay current liabilities / current liabilities ratio', '[{"en":"Accounts payable and short-term loans are current liabilities.","zh-TW":"應付帳款和短期貸款是流動負債。"},{"en":"High current liabilities relative to assets can signal liquidity risk.","zh-TW":"相對於資產的高流動負債可能表明流動性風險。"}]', NULL, NULL, 5, 1740, NULL),
(1741, 'current ratio', '/ˈkɜːrənt ˈreɪʃioʊ/', 'noun', '{"zh-TW":["流動比率"],"en":["a liquidity ratio comparing current assets to current liabilities"]}', NULL, 'calculate current ratio / maintain a current ratio', '[{"en":"A current ratio above 1 means a company can pay its short-term debts.","zh-TW":"流動比率高於1意味著公司能夠償還其短期債務。"},{"en":"The company improved its current ratio by collecting overdue receivables.","zh-TW":"公司通過催收逾期應收帳款改善了其流動比率。"}]', NULL, NULL, 5, 1741, NULL),
(1742, 'curriculum', '/kəˈrɪkjʊləm/', 'noun', '{"zh-TW":["課程；課程表"],"en":["the subjects in a course of study"]}', NULL, 'curriculum vitae / training curriculum; school curriculum / curriculum design', '[{"en":"Please submit your curriculum vitae.","zh-TW":"請提交你的履歷。"},{"en":"The training curriculum covers all essentials.","zh-TW":"培訓課程涵蓋了所有必備項目。"},{"en":"The school updated its curriculum.","zh-TW":"學校更新了課程。"},{"en":"Math is part of the core curriculum.","zh-TW":"數學是核心課程的一部分。"}]', '{"noun":"curriculum","adjective":"curricular","adjective2":"extracurricular"}', NULL, 4, 1742, NULL),
(1743, 'curriculum vitae', '/''kərɪkjʊləm ˌviːtaɪ/', 'noun', '{"zh-TW":["履歷；簡歷"],"en":["a brief account of a person''s education, qualifications, and previous experience"]}', NULL, 'submit a curriculum vitae / update your curriculum vitae / curriculum vitae requirements', '[{"en":"Most job applications require you to submit a curriculum vitae and cover letter.","zh-TW":"大多數求職申請要求你提交履歷和求職信。"},{"en":"She tailored her curriculum vitae to highlight her research experience.","zh-TW":"她調整了履歷，以突顯她的研究經驗。"}]', NULL, NULL, 5, 1743, NULL),
(1744, 'cursory', '/ˈkɜːrsəri/', 'adjective', '{"zh-TW":["粗略的；草率的"],"en":["hasty and therefore not thorough or detailed"]}', NULL, 'cursory glance / cursory review / cursory examination', '[{"en":"A cursory reading of the report misses important details.","zh-TW":"粗略閱讀報告會錯過重要細節。"},{"en":"The manager gave only a cursory review of the proposal.","zh-TW":"經理對提案只進行了粗略的審查。"}]', '{"adverb":"cursorily","noun":"cursoriness"}', NULL, 3, 1744, NULL),
(1745, 'curve', '/kɜːrv/', 'noun', '{"zh-TW":["曲線；彎道"],"en":["a smooth bending line"]}', NULL, 'learning curve / sharp curve', '[{"en":"There''s a sharp curve in the road.","zh-TW":"路上有一個急彎。"},{"en":"The learning curve is steep.","zh-TW":"學習曲線很陡峭。"}]', '{"adjective":"curved"}', NULL, 2, 1745, NULL),
(1746, 'custody', '/ˈkʌstədi/', 'noun', '{"zh-TW":["保管；監護","監護權；拘留"],"en":["the protective care or guardianship of something","the legal right to care for a child; being held by police"]}', '{"root":{"text":"cust","meaning":"guard (守護)"},"suffix":{"text":"-ody","meaning":"state (狀態)"},"logic":"守護的狀態，即「保管」。"}', 'in custody / custody of assets / safe custody; in custody / child custody', '[{"en":"Securities are held in safe custody by the bank.","zh-TW":"證券由銀行安全保管。"},{"en":"The documents are in the custody of the legal department.","zh-TW":"文件由法務部門保管。"},{"en":"She was awarded custody of the children.","zh-TW":"她獲得了孩子的監護權。"},{"en":"The suspect is in police custody.","zh-TW":"嫌疑人被警方拘留。"}]', '{"noun":"custodian"}', NULL, 3, 1746, NULL),
(1747, 'custom', '/ˈkʌstəm/', 'noun', '{"zh-TW":["習慣；海關","客製"],"en":["a traditional practice","duties charged on imports/exports"]}', '{"root":{"text":"custom","meaning":"habit/accustomed (習慣)"},"logic":"習慣的做法，即「習慣、海關」。"}', 'customs duty / local customs / custom-made', '[{"en":"The goods were held at customs for inspection.","zh-TW":"貨物在海關被扣留檢查。"},{"en":"We offer custom solutions tailored to your needs.","zh-TW":"我們提供量身定制的客製化解決方案。"}]', '{"noun":"customer","adjective":"customary","verb":"customize"}', NULL, 2, 1747, NULL),
(1748, 'customer', '/ˈkʌstəmər/', 'noun', '{"zh-TW":["顧客","顧客；客戶"],"en":["a person who buys goods or services"]}', '{"root":{"text":"custom","meaning":"habit (習慣)"},"suffix":{"text":"-er","meaning":"person who (…的人)"},"logic":"有消費習慣的人，即「顧客」。"}', 'regular customer / customer service; customer service / loyal customer', '[{"en":"The customer is always right.","zh-TW":"顧客永遠是對的。"},{"en":"We value our loyal customers.","zh-TW":"我們重視忠實顧客。"},{"en":"The customer asked for a refund.","zh-TW":"顧客要求退款。"}]', '{"noun":"custom","adjective":"customary"}', NULL, 3, 1748, 317),
(1749, 'customer acquisition', '/ˈkʌstəmər ˌækwɪˈzɪʃən/', 'noun', '{"zh-TW":["客戶獲取；客戶開發"],"en":["the process of gaining new customers"]}', NULL, 'customer acquisition strategy / customer acquisition cost', '[{"en":"Digital marketing reduced customer acquisition costs by 40%.","zh-TW":"數位行銷將客戶獲取成本降低了40%。"},{"en":"The focus shifted from customer acquisition to customer retention.","zh-TW":"重點從客戶獲取轉向了客戶保留。"}]', NULL, NULL, 5, 1749, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1750, 'customer acquisition cost', '/ˈkʌstəmər ˌækwɪˈzɪʃən kɒst/', 'noun', '{"zh-TW":["客戶獲取成本"],"en":["the cost of acquiring a new customer through marketing and sales efforts"]}', NULL, 'reduce customer acquisition cost / calculate customer acquisition cost', '[{"en":"High customer acquisition cost eroded the startup''s margins.","zh-TW":"高客戶獲取成本侵蝕了新創公司的利潤率。"},{"en":"Referral programs are used to reduce customer acquisition cost.","zh-TW":"推薦計劃用於降低客戶獲取成本。"}]', '{"abbreviation":"CAC"}', NULL, 5, 1750, NULL),
(1751, 'customer churn', '/ˈkʌstəmər tʃɜːrn/', 'noun', '{"zh-TW":["客戶流失；客戶流失率"],"en":["the rate at which customers stop doing business with a company"]}', NULL, 'reduce customer churn / customer churn rate', '[{"en":"High customer churn is a warning sign of poor service or value.","zh-TW":"高客戶流失率是服務或價值差的警告信號。"},{"en":"The company invested in loyalty programs to reduce customer churn.","zh-TW":"公司投資忠誠計劃以降低客戶流失。"}]', NULL, NULL, 5, 1751, NULL),
(1752, 'customer complaint', '/ˈkʌstəmər kəmˈpleɪnt/', 'noun', '{"zh-TW":["客戶投訴"],"en":["an expression of dissatisfaction from a customer about products or service"]}', NULL, 'handle a customer complaint / resolve a customer complaint', '[{"en":"Each customer complaint is logged and reviewed within 24 hours.","zh-TW":"每個客戶投訴都在24小時內記錄和審查。"},{"en":"A spike in customer complaints signals a quality or service issue.","zh-TW":"客戶投訴激增表明有品質或服務問題。"}]', NULL, NULL, 5, 1752, NULL),
(1753, 'customer experience', '/ˈkʌstəmər ɪkˈspɪəriənts/', 'noun', '{"zh-TW":["客戶體驗"],"en":["the overall impression a customer has of a brand throughout all interactions"]}', NULL, 'improve customer experience / customer experience strategy / measure customer experience', '[{"en":"Investing in customer experience led to a 25% increase in loyalty.","zh-TW":"投資客戶體驗帶來了25%的忠誠度提升。"},{"en":"Consistent customer experience across channels builds trust.","zh-TW":"跨渠道一致的客戶體驗建立信任。"}]', '{"abbreviation":"CX"}', NULL, 5, 1753, NULL),
(1754, 'customer journey', '/ˈkʌstəmər ˈdʒɜːrni/', 'noun', '{"zh-TW":["客戶旅程"],"en":["the complete experience a customer has with a company from awareness to purchase"]}', NULL, 'map the customer journey / optimize the customer journey / customer journey stages', '[{"en":"Mapping the customer journey revealed gaps in the buying process.","zh-TW":"繪製客戶旅程揭示了購買流程中的差距。"},{"en":"Improving the customer journey increased conversion rates.","zh-TW":"改善客戶旅程提高了轉換率。"}]', NULL, NULL, 5, 1754, NULL),
(1755, 'customer lifecycle', '/ˈkʌstəmər ˈlaɪfsaɪkəl/', 'noun', '{"zh-TW":["客戶生命週期"],"en":["the stages a customer goes through from first contact to end of relationship"]}', NULL, 'map the customer lifecycle / customer lifecycle management', '[{"en":"Understanding the customer lifecycle improves retention and upselling.","zh-TW":"了解客戶生命週期改善了留存率和追加銷售。"},{"en":"Tailored communications at each customer lifecycle stage increase loyalty.","zh-TW":"在客戶生命週期的每個階段提供量身定制的溝通提高了忠誠度。"}]', NULL, NULL, 5, 1755, NULL),
(1756, 'customer lifetime value', '/ˈkʌstəmər ˈlaɪftaɪm ˈvæljuː/', 'noun', '{"zh-TW":["客戶終身價值"],"en":["the total revenue a business expects from one customer over their lifetime"]}', NULL, 'increase customer lifetime value / calculate customer lifetime value', '[{"en":"Focusing on CLV is more profitable than chasing new customers.","zh-TW":"專注於客戶終身價值比追求新客戶更有利可圖。"},{"en":"Loyalty programs are designed to maximize customer lifetime value.","zh-TW":"忠誠度計劃旨在最大化客戶終身價值。"}]', '{"abbreviation":"CLV / LTV"}', NULL, 5, 1756, NULL),
(1757, 'customer loyalty', '/ˈkʌstəmər ˈlɔɪəlti/', 'noun', '{"zh-TW":["顧客忠誠度"],"en":["the tendency of a customer to repeatedly buy from a company"]}', NULL, 'build customer loyalty / customer loyalty program', '[{"en":"Customer loyalty programs reward repeat purchases.","zh-TW":"顧客忠誠度計劃獎勵重複購買。"},{"en":"Strong customer loyalty is built through trust and quality.","zh-TW":"強大的顧客忠誠度是透過信任和品質建立的。"}]', NULL, NULL, 5, 1757, NULL),
(1758, 'customer onboarding', '/ˈkʌstəmər ˈɒnbɔːrdɪŋ/', 'noun', '{"zh-TW":["客戶入門；客戶引導"],"en":["the process of helping new customers use and benefit from a product or service"]}', NULL, 'improve customer onboarding / customer onboarding experience', '[{"en":"A smooth customer onboarding experience reduces early churn.","zh-TW":"順暢的客戶入門體驗降低了早期流失率。"},{"en":"Customer onboarding includes welcome emails, tutorials, and support.","zh-TW":"客戶入門包括歡迎電子郵件、教程和支援。"}]', NULL, NULL, 5, 1758, NULL),
(1759, 'customer retention', '/ˈkʌstəmər rɪˈtenʃən/', 'noun', '{"zh-TW":["客戶保留；客戶留存"],"en":["the ability of a company to keep its existing customers over time"]}', NULL, 'improve customer retention / customer retention rate', '[{"en":"Loyalty programs are a key tool for customer retention.","zh-TW":"忠誠計劃是客戶保留的關鍵工具。"},{"en":"High customer retention reduces the cost of acquiring new clients.","zh-TW":"高客戶保留率降低了獲取新客戶的成本。"}]', NULL, NULL, 5, 1759, NULL),
(1760, 'customer satisfaction', '/ˈkʌstəmər ˌsætɪsˈfækʃən/', 'noun', '{"zh-TW":["客戶滿意度"],"en":["the measure of how well products or services meet customer expectations"]}', NULL, 'improve customer satisfaction / customer satisfaction score / customer satisfaction survey', '[{"en":"Customer satisfaction scores improved after the product update.","zh-TW":"產品更新後客戶滿意度分數有所提高。"},{"en":"High customer satisfaction leads to increased loyalty and referrals.","zh-TW":"高客戶滿意度帶來更高的忠誠度和推薦率。"}]', '{"abbreviation":"CSAT","adjective":"satisfied"}', NULL, 5, 1760, NULL),
(1761, 'customer segmentation', '/ˈkʌstəmər ˌseɡmenˈteɪʃən/', 'noun', '{"zh-TW":["客戶細分"],"en":["dividing customers into groups based on shared characteristics"]}', NULL, 'apply customer segmentation / customer segmentation strategy', '[{"en":"Customer segmentation allows for targeted marketing campaigns.","zh-TW":"客戶細分允許有針對性的行銷活動。"},{"en":"The company used customer segmentation to improve service personalization.","zh-TW":"公司使用客戶細分改善了服務個性化。"}]', NULL, NULL, 5, 1761, NULL),
(1762, 'customer service', '/ˈkʌstəmər ˈsɜːrvɪs/', 'noun', '{"zh-TW":["客戶服務"],"en":["assistance and advice provided to customers before and after purchasing"]}', NULL, 'customer service team / customer service training / improve customer service', '[{"en":"Excellent customer service drives repeat business and referrals.","zh-TW":"出色的客戶服務推動了回頭客和推薦業務。"},{"en":"The customer service team handles over 500 inquiries daily.","zh-TW":"客戶服務團隊每天處理超過500個查詢。"}]', '{"noun":"customer service representative"}', NULL, 5, 1762, NULL),
(1763, 'customer service representative', '/ˈkʌstəmər ˈsɜːrvɪs ˌrɛprɪˈzɛntətɪv/', 'noun', '{"zh-TW":["客服代表"],"en":["an employee who handles customer inquiries and complaints"]}', NULL, 'contact a customer service representative / train customer service representatives', '[{"en":"The customer service representative resolved the issue immediately.","zh-TW":"客服代表立即解決了問題。"},{"en":"Friendly customer service representatives improve satisfaction scores.","zh-TW":"友善的客服代表提高了滿意度評分。"}]', NULL, NULL, 5, 1763, NULL),
(1764, 'customize', 'ˈkʌstəmaɪz', 'verb', '{"zh-TW":["客製化；定制","個性化"],"en":["to modify to specific needs","to personalize"]}', NULL, 'customize a product/customize a service', '[{"en":"We can customize the service to your needs.","zh-TW":"我們可以根據您的需求定制服務。"}]', '{"noun":"customization","adjective":"customized"}', NULL, 3, 1764, 318),
(1765, 'customs', '/ˈkʌstəmz/', 'noun', '{"zh-TW":["海關"],"en":["the official process of checking goods entering a country"]}', NULL, 'pass through customs / customs declaration', '[{"en":"All passengers must pass through customs upon arrival.","zh-TW":"所有乘客抵達時須通過海關。"},{"en":"Please declare any items over the duty-free limit.","zh-TW":"請申報超過免稅限額的物品。"}]', '{"adjective":"customary"}', NULL, 3, 1765, NULL),
(1766, 'customs broker', '/ˈkʌstəmz ˈbroʊkər/', 'noun', '{"zh-TW":["報關行；海關代理人"],"en":["a licensed agent who handles import and export customs procedures for businesses"]}', NULL, 'appoint a customs broker / customs broker fee', '[{"en":"The customs broker ensured all documentation met import regulations.","zh-TW":"報關行確保所有文件符合進口法規。"},{"en":"Using a customs broker reduces clearance delays and compliance errors.","zh-TW":"使用報關行減少了清關延誤和合規錯誤。"}]', NULL, NULL, 5, 1766, NULL),
(1767, 'customs clearance', '/ˈkʌstəmz ˈklɪərəns/', 'noun', '{"zh-TW":["通關；清關"],"en":["the process of getting goods through customs"]}', NULL, 'expedite customs clearance / customs clearance process', '[{"en":"Proper documentation speeds up customs clearance.","zh-TW":"適當的文件加快了通關程序。"},{"en":"The goods were held up awaiting customs clearance.","zh-TW":"貨物因等待通關而被扣押。"}]', NULL, NULL, 5, 1767, NULL),
(1768, 'customs declaration', '/ˈkʌstəmz ˌdɛkləˈreɪʃən/', 'noun', '{"zh-TW":["海關申報"],"en":["a form listing items brought into a country"]}', NULL, 'fill out a customs declaration / customs declaration form', '[{"en":"Please complete the customs declaration form honestly.","zh-TW":"請如實填寫海關申報單。"},{"en":"Undeclared goods may be confiscated at customs.","zh-TW":"未申報的物品可能在海關被沒收。"}]', NULL, NULL, 5, 1768, NULL),
(1769, 'customs duty', '/ˈkʌstəmz ˈdjuːti/', 'noun', '{"zh-TW":["關稅"],"en":["a tax levied on goods imported into a country"]}', NULL, 'pay customs duty / customs duty rate / exempt from customs duty', '[{"en":"High customs duties made the imported goods uncompetitive.","zh-TW":"高關稅使進口商品失去競爭力。"},{"en":"The company applied for an exemption from customs duty on raw materials.","zh-TW":"公司申請了原材料的關稅豁免。"}]', '{"plural":"customs duties"}', NULL, 4, 1769, NULL),
(1770, 'cut', '/kʌt/', 'verb', '{"zh-TW":["切；削減"],"en":["to divide with a sharp instrument","to reduce"]}', NULL, 'cut costs / cut back', '[{"en":"We need to cut costs by 10%.","zh-TW":"我們需要削減10%的成本。"},{"en":"The company cut 200 jobs.","zh-TW":"公司裁減了200個職位。"}]', '{"verb":"cut","noun":"cut","noun2":"cutback"}', NULL, 1, 1770, NULL),
(1771, 'cut costs', '/kʌt kɒsts/', 'verb', '{"zh-TW":["削減成本"],"en":["to reduce spending or operating expenses"]}', NULL, 'cut costs aggressively / cut costs across the board', '[{"en":"The company cut costs by reducing travel and entertainment expenses.","zh-TW":"公司通過減少差旅和娛樂費用削減了成本。"},{"en":"Cutting costs without affecting quality is a major management challenge.","zh-TW":"在不影響品質的情況下削減成本是一大管理挑戰。"}]', NULL, NULL, 3, 1771, NULL),
(1772, 'cute', '/kjuːt/', 'adjective', '{"zh-TW":["可愛的"],"en":["attractive in a pretty way"]}', NULL, 'cute baby / cute outfit', '[{"en":"What a cute puppy!","zh-TW":"好可愛的小狗！"},{"en":"That''s a cute outfit.","zh-TW":"那套衣服很可愛。"}]', '{"noun":"cuteness"}', NULL, 1, 1772, NULL),
(1773, 'cutlery', '/ˈkʌtlərɪ/', 'noun', '{"zh-TW":["餐具；刀叉"],"en":["knives, forks, and spoons used for eating"]}', NULL, 'clean cutlery / provide cutlery', '[{"en":"Please set the table with the correct cutlery.","zh-TW":"請用正確的餐具擺好桌子。"},{"en":"The restaurant uses only high-quality cutlery.","zh-TW":"餐廳只使用高品質的餐具。"}]', NULL, NULL, 3, 1773, NULL),
(1774, 'cutoff date', '/''kʌtɒf deɪt/', 'noun', '{"zh-TW":["截止日期；最後期限"],"en":["the last date by which something must be done or received"]}', NULL, 'meet the cutoff date / miss the cutoff date / cutoff date reminder', '[{"en":"Applications received after the cutoff date will not be considered.","zh-TW":"在截止日期後收到的申請將不予考慮。"},{"en":"She submitted her portfolio three days before the cutoff date.","zh-TW":"她在截止日期前三天提交了她的作品集。"}]', NULL, NULL, 4, 1774, NULL),
(1775, 'cybersecurity', '/ˌsaɪbərsɪˈkjʊrɪti/', 'noun', '{"zh-TW":["網路安全"],"en":["protection of computers and networks from attack"]}', NULL, 'cybersecurity threat / cybersecurity expert', '[{"en":"Cybersecurity is a growing concern.","zh-TW":"網路安全是日益受關注的議題。"},{"en":"She works in cybersecurity.","zh-TW":"她從事網路安全工作。"}]', NULL, NULL, 5, 1775, NULL),
(1776, 'cycle', '/ˈsaɪkl/', 'noun', '{"zh-TW":["週期；循環","循環；周期；自行車"],"en":["a series of events that are regularly repeated","a series of events that repeat"]}', '{"root":{"text":"cycl","meaning":"circle (圓)"},"suffix":{"text":"-e","meaning":"noun ending"},"logic":"圓形的重複，即「週期」。"}', 'business cycle / product life cycle / billing cycle; life cycle / business cycle', '[{"en":"The business cycle affects hiring decisions.","zh-TW":"商業週期影響招聘決策。"},{"en":"The product is at the end of its life cycle.","zh-TW":"產品已處於其生命週期的末端。"},{"en":"The seasons follow a cycle.","zh-TW":"季節遵循一個循環。"},{"en":"She cycles to work every day.","zh-TW":"她每天騎自行車上班。"}]', '{"adjective":"cyclical","verb":"cycle","noun2":"cyclist"}', NULL, 2, 1776, NULL),
(1777, 'cycle time', '/ˈsaɪkəl taɪm/', 'noun', '{"zh-TW":["週期時間"],"en":["the total time from the start to the completion of one unit of work or product"]}', NULL, 'reduce cycle time / measure cycle time', '[{"en":"Automation reduced the production cycle time from 8 hours to 3 hours.","zh-TW":"自動化將生產週期時間從8小時縮短到了3小時。"},{"en":"A shorter cycle time allows the company to fulfill orders faster.","zh-TW":"較短的週期時間使公司能夠更快地完成訂單。"}]', NULL, NULL, 4, 1777, NULL),
(1778, 'cyclical', '/ˈsɪklɪkəl/', 'adjective', '{"zh-TW":["週期性的；循環的"],"en":["recurring in regular cycles, often related to economic conditions"]}', NULL, 'cyclical industry / cyclical demand / cyclical stock', '[{"en":"Tourism is a highly cyclical industry tied to economic conditions.","zh-TW":"旅遊業是一個高度週期性的行業，與經濟條件密切相關。"},{"en":"Investors reduce exposure to cyclical stocks during downturns.","zh-TW":"在低迷時期，投資者減少對週期性股票的敞口。"}]', '{"adverb":"cyclically","noun":"cycle"}', NULL, 3, 1778, NULL),
(1779, 'cycling', '/''saɪklɪŋ/', 'noun', '{"zh-TW":["騎自行車；自行車運動"],"en":["the sport or activity of riding a bicycle"]}', NULL, 'go cycling / competitive cycling / cycling club', '[{"en":"Cycling is a low-impact exercise that is gentle on the joints.","zh-TW":"騎自行車是一種對關節溫和的低衝擊運動。"},{"en":"She joined a cycling club that organizes weekly group rides through the hills.","zh-TW":"她加入了一個每週組織穿越山丘的團體騎行自行車俱樂部。"}]', '{"verb":"cycle","noun2":"cyclist"}', NULL, 3, 1779, NULL),
(1780, 'cyclone', '/ˈsaɪkloʊn/', 'noun', '{"zh-TW":["氣旋；颶風"],"en":["a violent rotating windstorm"]}', '{"root":{"text":"cycl","meaning":"circle (圓)"},"suffix":{"text":"-one","meaning":"thing (物)"},"logic":"旋轉如圓的風暴。"}', 'tropical cyclone / cyclone warning', '[{"en":"The cyclone caused widespread destruction.","zh-TW":"氣旋造成大範圍的破壞。"},{"en":"A tropical cyclone is approaching the coast.","zh-TW":"一個熱帶氣旋正在逼近海岸。"}]', '{"adjective":"cyclonic"}', NULL, 3, 1780, NULL),
(1781, 'dad', '/dæd/', 'noun', '{"zh-TW":["爸爸"],"en":["a father"]}', NULL, 'my dad / dad joke', '[{"en":"My dad taught me to drive.","zh-TW":"我爸爸教我開車。"},{"en":"He''s a great dad.","zh-TW":"他是個好爸爸。"}]', NULL, NULL, 1, 1781, NULL),
(1782, 'daily', '/ˈdeɪli/', 'adjective', '{"zh-TW":["每日的"],"en":["happening every day"]}', NULL, 'daily routine / daily life', '[{"en":"Exercise is part of my daily routine.","zh-TW":"運動是我日常作息的一部分。"},{"en":"The newspaper is published daily.","zh-TW":"報紙每天出版。"}]', NULL, NULL, 2, 1782, NULL),
(1783, 'daily special', '/ˈdeɪli ˈspɛʃəl/', 'noun', '{"zh-TW":["每日特餐"],"en":["a dish that changes each day"]}', NULL, 'today''s daily special / ask about the daily special', '[{"en":"The daily special today is grilled salmon with vegetables.","zh-TW":"今日特餐是烤鮭魚配蔬菜。"},{"en":"Ask the server what the daily special is.","zh-TW":"請詢問服務員今日特餐是什麼。"}]', NULL, NULL, 5, 1783, NULL),
(1784, 'damage', '/ˈdæmɪdʒ/', 'noun / verb', '{"zh-TW":["損害；損壞"],"en":["physical harm that impairs value or usefulness"]}', NULL, 'cause/suffer damage', '[{"en":"The storm caused severe damage to the building.","zh-TW":"暴風雨對建築物造成了嚴重損害。"},{"en":"Smoking can damage your health.","zh-TW":"吸菸會損害你的健康。"}]', '{"noun":"damage","verb":"damage","adjective":"damaged"}', NULL, 2, 1784, NULL),
(1785, 'damages', '/ˈdæmɪdʒɪz/', 'noun', '{"zh-TW":["損害賠償金"],"en":["money claimed as compensation for loss or injury"]}', NULL, 'claim damages / award damages', '[{"en":"The court awarded damages to the injured party.","zh-TW":"法院向受傷方判決損害賠償金。"},{"en":"The company was ordered to pay damages for breach of contract.","zh-TW":"公司被命令支付違約損害賠償金。"}]', '{"verb":"damage","adjective":"damaged"}', NULL, 3, 1785, NULL),
(1786, 'dance', '/dæns/', 'verb', '{"zh-TW":["跳舞；舞蹈"],"en":["to move rhythmically to music"]}', NULL, 'dance class / dance floor', '[{"en":"They danced at the company gala.","zh-TW":"他們在公司晚會上跳舞。"},{"en":"She teaches dance classes on weekends.","zh-TW":"她週末教舞蹈課。"}]', '{"verb":"dance","noun":"dance","noun2":"dancer","noun3":"dancing"}', NULL, 2, 1786, NULL),
(1787, 'danger', '/ˈdeɪndʒər/', 'noun', '{"zh-TW":["危險"],"en":["the possibility of harm or damage","the possibility of harm or death"]}', NULL, 'in danger / danger zone; in danger / out of danger', '[{"en":"Workers are in danger without proper equipment.","zh-TW":"沒有適當裝備，工人會有危險。"},{"en":"There is a danger of flooding.","zh-TW":"有發生洪水的危險。"},{"en":"The building is in danger of collapsing.","zh-TW":"這棟建築有倒塌的危險。"},{"en":"The patient is out of danger now.","zh-TW":"病人已經脫離危險了。"}]', '{"noun":"danger","adjective":"dangerous","adverb":"dangerously","verb":"endanger"}', NULL, 2, 1787, NULL),
(1788, 'dangerous', 'ˈdeɪndʒərəs', 'adjective', '{"zh-TW":["危險的；有害的","冒險的"],"en":["likely to cause harm","risky"]}', NULL, 'dangerous condition/dangerous product', '[{"en":"The factory reported a dangerous gas leak.","zh-TW":"工廠報告了危險的氣體洩漏。"}]', '{"noun":"danger","adverb":"dangerously"}', NULL, 3, 1788, NULL),
(1789, 'dark', '/dɑːrk/', 'adjective', '{"zh-TW":["黑暗的；深色的"],"en":["with little or no light","closer to black"]}', NULL, 'in the dark / dark color; in the dark / dark side', '[{"en":"We were kept in the dark about the changes.","zh-TW":"我們被蒙在鼓裡不知道有變動。"},{"en":"She prefers dark colors for business wear.","zh-TW":"她上班穿著偏好深色系。"},{"en":"It gets dark early in winter.","zh-TW":"冬天天黑得早。"},{"en":"She has dark brown hair.","zh-TW":"她有深棕色的頭髮。"}]', '{"adjective":"dark","noun":"darkness","verb":"darken","adverb":"darkly"}', NULL, 1, 1789, NULL),
(1790, 'data', '/ˈdeɪtə/', 'noun', '{"zh-TW":["資料；數據"],"en":["facts and information collected together"]}', NULL, 'data analysis / big data', '[{"en":"We need more data to decide.","zh-TW":"我們需要更多數據來做決定。"},{"en":"Big data is transforming business.","zh-TW":"大數據正在改變商業。"}]', NULL, NULL, 1, 1790, NULL),
(1791, 'data analytics', '/ˈdeɪtə ænəˈlɪtɪks/', 'noun', '{"zh-TW":["數據分析"],"en":["examining raw data to draw conclusions and support decision-making"]}', NULL, 'data analytics tools / data analytics platform / leverage data analytics', '[{"en":"Data analytics revealed patterns in customer purchasing behavior.","zh-TW":"數據分析揭示了客戶購買行為的模式。"},{"en":"The company uses data analytics to optimize its marketing spend.","zh-TW":"公司使用數據分析優化其行銷支出。"}]', '{"noun":"data analyst","adjective":"data-driven"}', NULL, 5, 1791, NULL),
(1792, 'data breach', '/ˈdeɪtə briːtʃ/', 'noun', '{"zh-TW":["數據洩露；資料外洩"],"en":["unauthorized access to confidential data"]}', NULL, 'report a data breach / respond to a data breach', '[{"en":"The company suffered a major data breach affecting 500,000 customers.","zh-TW":"公司遭遇了影響500,000名顧客的重大數據洩露。"},{"en":"A data breach response plan must be in place before an incident occurs.","zh-TW":"數據洩露應對計劃必須在事件發生前就位。"}]', NULL, NULL, 4, 1792, NULL),
(1793, 'data center', '/ˈdeɪtə ˈsentər/', 'noun', '{"zh-TW":["資料中心"],"en":["a facility housing computer systems for data storage and management"]}', NULL, 'operate a data center / data center efficiency / hyperscale data center', '[{"en":"Major cloud providers operate data centers on every continent.","zh-TW":"主要雲服務提供商在每個大洲都運營著資料中心。"},{"en":"Data center energy consumption is a growing environmental concern.","zh-TW":"資料中心能源消耗是日益增長的環境問題。"}]', NULL, NULL, 4, 1793, NULL),
(1794, 'data entry', '/ˈdeɪtə ˈentri/', 'noun', '{"zh-TW":["資料輸入"],"en":["the process of manually entering data into a computer system"]}', NULL, 'automate data entry / data entry error', '[{"en":"Automating data entry reduced processing time by 60%.","zh-TW":"自動化資料輸入將處理時間縮短了60%。"},{"en":"Data entry errors were the main cause of reconciliation differences.","zh-TW":"資料輸入錯誤是對帳差異的主要原因。"}]', NULL, NULL, 4, 1794, NULL),
(1795, 'data governance', '/ˈdeɪtə ˈɡʌvənəns/', 'noun', '{"zh-TW":["資料治理"],"en":["the management of data availability, integrity, and security within an organization"]}', NULL, 'establish data governance / data governance framework', '[{"en":"The data governance policy defines who can access sensitive information.","zh-TW":"資料治理政策定義了誰可以存取敏感資訊。"},{"en":"Strong data governance ensures compliance with privacy regulations.","zh-TW":"強力的資料治理確保遵守隱私法規。"}]', NULL, NULL, 5, 1795, NULL),
(1796, 'data lake', '/ˈdeɪtə leɪk/', 'noun', '{"zh-TW":["數據湖"],"en":["a centralized repository storing vast amounts of raw data in native format"]}', NULL, 'build a data lake / enterprise data lake / data lake architecture', '[{"en":"The company built a data lake to consolidate data from all business units.","zh-TW":"公司建立了數據湖，整合來自所有業務單元的數據。"},{"en":"A data lake differs from a data warehouse in that it stores raw, unstructured data.","zh-TW":"數據湖與數據倉庫的不同之處在於它存儲原始的非結構化數據。"}]', NULL, NULL, 3, 1796, NULL),
(1797, 'data management', '/ˈdeɪtə ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["資料管理"],"en":["the collection, storage, and maintenance of data to ensure accuracy and availability"]}', NULL, 'improve data management / data management system', '[{"en":"Good data management ensures reliable reporting.","zh-TW":"良好的資料管理確保了可靠的報告。"},{"en":"Data management practices must comply with privacy regulations.","zh-TW":"資料管理實踐必須遵守隱私法規。"}]', NULL, NULL, 5, 1797, NULL),
(1798, 'data mining', '/ˈdeɪtə ˌmaɪnɪŋ/', 'noun', '{"zh-TW":["資料挖掘"],"en":["analyzing large datasets to discover patterns and relationships"]}', NULL, 'use data mining / data mining tools / data mining techniques', '[{"en":"Data mining revealed unexpected purchasing patterns.","zh-TW":"資料挖掘揭示了意想不到的購買模式。"},{"en":"The marketing team used data mining to identify high-value customers.","zh-TW":"市場行銷團隊使用資料挖掘來識別高價值客戶。"}]', '{"verb":"mine data"}', NULL, 4, 1798, NULL),
(1799, 'data pipeline', '/ˈdeɪtə ˈpaɪplaɪn/', 'noun', '{"zh-TW":["數據管道"],"en":["a series of processes that move and transform data from source to destination"]}', NULL, 'build a data pipeline / data pipeline architecture / automated data pipeline', '[{"en":"The data pipeline ingests raw sensor data and outputs cleaned reports.","zh-TW":"數據管道攝取原始感測器數據並輸出清理後的報告。"},{"en":"A robust data pipeline is critical for real-time analytics.","zh-TW":"健壯的數據管道對於即時分析至關重要。"}]', NULL, NULL, 5, 1799, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1800, 'data privacy', '/ˈdeɪtə ˈprɪvəsi/', 'noun', '{"zh-TW":["數據隱私；資料隱私"],"en":["the protection of personal information from unauthorized access"]}', NULL, 'ensure data privacy / data privacy policy', '[{"en":"The company is committed to protecting customer data privacy.","zh-TW":"公司致力於保護顧客的數據隱私。"},{"en":"Data privacy regulations require explicit consent before collection.","zh-TW":"數據隱私法規要求在收集前獲得明確同意。"}]', NULL, NULL, 4, 1800, NULL),
(1801, 'data visualization', '/ˈdeɪtə ˌvɪʒuəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["資料視覺化"],"en":["presenting data in graphical form to make patterns and insights clear"]}', NULL, 'data visualization tools / effective data visualization / data visualization dashboard', '[{"en":"Data visualization made complex sales trends easy to understand.","zh-TW":"資料視覺化使複雜的銷售趨勢易於理解。"},{"en":"Interactive data visualization enables faster business decisions.","zh-TW":"互動式資料視覺化實現更快的商業決策。"}]', '{"verb":"visualize data"}', NULL, 5, 1801, NULL),
(1802, 'data-driven', 'ˈdeɪtə ˈdrɪvən', 'adjective', '{"zh-TW":["數據驅動的；基於數據的","以事實為依據的"],"en":["based on analysis of data","using evidence to decide"]}', NULL, 'data-driven decision/data-driven approach', '[{"en":"Our strategy is completely data-driven.","zh-TW":"我們的策略完全基於數據。"}]', NULL, NULL, 4, 1802, NULL),
(1803, 'data-driven decision', '/''deɪtə ˌdrɪvən dɪˌsɪʒən/', 'noun', '{"zh-TW":["數據驅動決策"],"en":["a decision made based on analysis of data rather than intuition or opinion"]}', NULL, 'make a data-driven decision / data-driven decision process / support data-driven decisions', '[{"en":"Leaders who make data-driven decisions are more likely to achieve consistent results.","zh-TW":"做出數據驅動決策的領導者更可能取得一致的結果。"},{"en":"The company adopted a data-driven decision approach to improve marketing ROI.","zh-TW":"公司採用數據驅動決策方法來提高行銷投資回報率。"}]', '{"adjective":"data-driven"}', NULL, 5, 1803, NULL),
(1804, 'database', '/ˈdeɪtəbeɪs/', 'noun', '{"zh-TW":["資料庫"],"en":["an organized collection of stored data"]}', NULL, 'customer database / update the database', '[{"en":"The customer database contains over one million records.","zh-TW":"顧客資料庫包含超過一百萬筆記錄。"},{"en":"Access to the database requires a password.","zh-TW":"訪問資料庫需要密碼。"}]', NULL, NULL, 3, 1804, 319),
(1805, 'date', 'deɪt', 'noun', '{"zh-TW":["【主要意義-名詞】日期；約會","【次要意義-動詞】過時；使顯得老舊","【次要意義-動詞】追溯到（歷史）；確定年代"],"en":["[primary - noun] a specific day; a romantic appointment","[secondary - verb] to become or appear old-fashioned","[secondary - verb] to determine the age of something; to originate from a time"]}', NULL, 'date back to / out of date / up to date / date from', '[{"en":"This management style is beginning to date and needs updating.","zh-TW":"這種管理風格開始顯得過時，需要更新。"},{"en":"The company dates back to 1923 and has a long trading history.","zh-TW":"該公司可追溯到1923年，有悠久的貿易歷史。"},{"en":"Please ensure all information on the form is up to date.","zh-TW":"請確保表格上的所有資訊都是最新的。"}]', '{"adjective":"dated, outdated"}', '動詞 date 意為「過時」或「追溯到」，片語 date back to（追溯至）和 up to date（最新的）是 TOEIC 閱讀文章和公告中的高頻表達。', 1, 1805, NULL),
(1806, 'daughter', '/ˈdɔːtər/', 'noun', '{"zh-TW":["女兒"],"en":["a female child"]}', NULL, 'daughter company / eldest daughter; eldest daughter / daughter-in-law', '[{"en":"His daughter works at the same company.","zh-TW":"他的女兒在同一家公司工作。"},{"en":"The daughter company handles overseas sales.","zh-TW":"子公司負責海外銷售。"},{"en":"They have two daughters.","zh-TW":"他們有兩個女兒。"},{"en":"My daughter is ten years old.","zh-TW":"我女兒十歲了。"}]', '{"noun":"daughter"}', NULL, 3, 1806, NULL),
(1807, 'daunting', '/''dɔːntɪŋ/', 'adjective', '{"zh-TW":["令人畏懼的；使人氣餒的"],"en":["seeming difficult to deal with in anticipation; intimidating"]}', NULL, 'daunting task / daunting prospect / daunting challenge', '[{"en":"Learning a new language can seem daunting at first, but persistence pays off.","zh-TW":"學習一門新語言起初可能看起來令人畏懼，但堅持不懈會有回報。"},{"en":"The daunting scale of the project required careful planning and resource allocation.","zh-TW":"項目令人生畏的規模需要仔細的規劃和資源分配。"}]', '{"verb":"daunt","adverb":"dauntingly"}', NULL, 3, 1807, NULL),
(1808, 'day rate', '/deɪ reɪt/', 'noun', '{"zh-TW":["日費率；日薪"],"en":["a charge or pay rate calculated on a daily basis"]}', NULL, 'agree on a day rate / consultant day rate', '[{"en":"The contractor''s day rate was $800 for on-site work.","zh-TW":"承包商的現場工作日費率為800元。"},{"en":"Day rates for specialized consultants vary widely by industry.","zh-TW":"專業顧問的日費率因行業不同而差異很大。"}]', NULL, NULL, 3, 1808, NULL),
(1809, 'day trip', '/''deɪ trɪp/', 'noun', '{"zh-TW":["一日遊；當日來回旅行"],"en":["a trip or excursion completed in a single day"]}', NULL, 'take a day trip / organize a day trip / day trip destination', '[{"en":"We took a day trip to the nearby coastal town and returned by evening.","zh-TW":"我們去附近的海濱小鎮一日遊，傍晚前返回。"},{"en":"A day trip from Paris to Versailles is highly recommended for first-time visitors.","zh-TW":"從巴黎到凡爾賽的一日遊對初次訪客來說是強烈推薦的。"}]', NULL, NULL, 3, 1809, NULL),
(1810, 'days payable outstanding', '/deɪz ˈpeɪəbl aʊtˈstændɪŋ/', 'noun', '{"zh-TW":["應付帳款天數"],"en":["the average number of days a company takes to pay its suppliers"]}', NULL, 'calculate days payable outstanding / improve days payable outstanding', '[{"en":"Extending days payable outstanding improves short-term cash flow.","zh-TW":"延長應付帳款天數改善了短期現金流。"},{"en":"A high days payable outstanding may indicate cash flow stress.","zh-TW":"高應付帳款天數可能表明現金流壓力。"}]', '{"abbreviation":"DPO"}', NULL, 5, 1810, NULL),
(1811, 'days sales outstanding', '/deɪz seɪlz ˌaʊtˈstændɪŋ/', 'noun', '{"zh-TW":["應收帳款天數；銷售未收款天數"],"en":["the average number of days it takes to collect payment after a sale"]}', NULL, 'reduce days sales outstanding / calculate days sales outstanding', '[{"en":"The company reduced its days sales outstanding from 60 to 45 days.","zh-TW":"公司將應收帳款天數從60天縮短到了45天。"},{"en":"A lower days sales outstanding indicates more efficient cash collection.","zh-TW":"較低的應收帳款天數表明更高效的現金收款。"}]', '{"abbreviation":"DSO"}', NULL, 5, 1811, NULL),
(1812, 'dead', '/dɛd/', 'adjective', '{"zh-TW":["死的；無生命的"],"en":["no longer alive","not working"]}', NULL, 'deadline / dead end; dead end / dead silence', '[{"en":"My phone battery is dead.","zh-TW":"我的手機沒電了。"},{"en":"The negotiations reached a dead end.","zh-TW":"談判陷入了僵局。"},{"en":"The flowers are dead.","zh-TW":"花都枯死了。"},{"en":"We reached a dead end.","zh-TW":"我們走到了死路。"}]', '{"adjective":"dead","noun":"death","verb":"die","adjective2":"deadly"}', NULL, 1, 1812, NULL),
(1813, 'dead cat bounce', '/ded kæt baʊns/', 'noun', '{"zh-TW":["死貓彈跳；短暫反彈"],"en":["a temporary recovery in the price of a falling asset that is not followed by a true recovery"]}', NULL, 'recognize a dead cat bounce / dead cat bounce pattern / avoid buying on dead cat bounce', '[{"en":"Traders warned that the stock''s recovery was a dead cat bounce before further declines.","zh-TW":"交易員警告說，該股的反彈是進一步下跌前的死貓彈跳。"},{"en":"After a sharp drop, a dead cat bounce can mislead investors into thinking the trend has reversed.","zh-TW":"在急劇下跌後，死貓彈跳可能會誤導投資者認為趨勢已經逆轉。"}]', NULL, NULL, 5, 1813, NULL),
(1814, 'deadline', '/ˈdedlaɪn/', 'noun', '{"zh-TW":["截止期限；最後期限","截止期限"],"en":["a date or time by which something must be done","the latest time by which something must be completed"]}', '{"root":{"text":"dead","meaning":"absolute (絕對)"},"suffix":{"text":"line","meaning":"line (線)"},"logic":"絕對不能越過的時間線。"}', 'meet/miss a deadline; meet the deadline / miss the deadline / tight deadline', '[{"en":"The deadline for applications is next Friday.","zh-TW":"申請的截止日期是下週五。"},{"en":"We need to meet the deadline.","zh-TW":"我們必須在截止日期前完成。"},{"en":"The deadline for applications is Friday.","zh-TW":"申請截止日期是週五。"},{"en":"We need to meet the deadline.","zh-TW":"我們需要趕上截止期限。"}]', '{"noun":"deadline"}', NULL, 3, 1814, 21),
(1815, 'deadline extension', '/ˈdedlaɪn ɪkˈstenʃən/', 'noun', '{"zh-TW":["截止日期延長"],"en":["granting additional time beyond an original deadline"]}', NULL, 'request a deadline extension / grant a deadline extension', '[{"en":"She requested a deadline extension due to unexpected technical issues.","zh-TW":"她因意外的技術問題要求延長截止日期。"},{"en":"A two-week deadline extension was approved by the client.","zh-TW":"客戶批准了兩週的截止日期延長。"}]', NULL, NULL, 5, 1815, NULL),
(1816, 'deadline management', '/ˈdɛdlaɪn ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["截止日期管理"],"en":["the skill of completing tasks on time"]}', NULL, 'effective deadline management / deadline management skills', '[{"en":"Effective deadline management is essential for project success.","zh-TW":"有效的截止日期管理對項目成功至關重要。"},{"en":"She is praised for her excellent deadline management skills.","zh-TW":"她因出色的截止日期管理技能而受到稱讚。"}]', NULL, NULL, 5, 1816, NULL),
(1817, 'deadline-driven', '/ˈdedlaɪn ˈdrɪvən/', 'adjective', '{"zh-TW":["以截止日期為導向的"],"en":["motivated by or working to specific deadlines"]}', NULL, 'deadline-driven culture / deadline-driven team', '[{"en":"The agency operates in a fast-paced, deadline-driven environment.","zh-TW":"該機構在快節奏、以截止日期為導向的環境中運作。"},{"en":"She thrives in deadline-driven roles where pace is high.","zh-TW":"她在節奏快、以截止日期為導向的職位中表現出色。"}]', NULL, NULL, 5, 1817, NULL),
(1818, 'deal', '/diːl/', 'noun', '{"zh-TW":["交易；協議"],"en":["an agreement; a bargain"]}', NULL, 'big deal / deal with', '[{"en":"We made a deal.","zh-TW":"我們達成了一筆交易。"},{"en":"It''s not a big deal.","zh-TW":"這沒什麼大不了的。"}]', '{"verb":"deal","noun2":"dealer"}', NULL, 1, 1818, 320),
(1819, 'dealing room', '/ˈdiːlɪŋ ruːm/', 'noun', '{"zh-TW":["交易室；交易大廳"],"en":["an office area where financial traders buy and sell securities"]}', NULL, 'work in the dealing room / dealing room operations', '[{"en":"The dealing room handles over 10 billion in daily transactions.","zh-TW":"交易室每天處理超過100億元的交易。"},{"en":"Electronic trading has reduced the size of many dealing rooms.","zh-TW":"電子交易縮小了許多交易室的規模。"}]', NULL, NULL, 4, 1819, NULL),
(1820, 'dean', '/diːn/', 'noun', '{"zh-TW":["院長；系主任"],"en":["the head of a university department"]}', NULL, 'dean''s list / dean of students', '[{"en":"She was named to the dean''s list.","zh-TW":"她被列入院長嘉許名單。"},{"en":"The dean approved the new course.","zh-TW":"院長批准了新課程。"}]', NULL, NULL, 1, 1820, NULL),
(1821, 'dean''s list', '/''diːnz lɪst/', 'noun', '{"zh-TW":["優秀學生名單；院長名單"],"en":["a list of students who have achieved the highest academic performance at a college or university"]}', NULL, 'make the dean''s list / appear on the dean''s list / dean''s list recognition', '[{"en":"She made the dean''s list every semester of her undergraduate studies.","zh-TW":"她在大學每個學期都上了優秀學生名單。"},{"en":"Being on the dean''s list demonstrates consistent academic excellence.","zh-TW":"出現在優秀學生名單上表明了持續的卓越學術成就。"}]', NULL, NULL, 4, 1821, NULL),
(1822, 'debarkation', '/''diːbɑːrˈkeɪʃən/', 'noun', '{"zh-TW":["下船；離機；登陸"],"en":["the process of disembarking from a ship, aircraft, or other vehicle"]}', NULL, 'debarkation lounge / orderly debarkation / debarkation point', '[{"en":"Debarkation from the cruise ship took about two hours due to the large number of passengers.","zh-TW":"由於乘客眾多，從遊輪下船花了約兩個小時。"},{"en":"Passengers were asked to wait in the debarkation lounge until their row was called.","zh-TW":"乘客被要求在下機候機廳等待，直到叫到他們所在排。"}]', NULL, NULL, 4, 1822, NULL),
(1823, 'debatable', '/''dɪˌbeɪtəbəl/', 'adjective', '{"zh-TW":["有爭議的；可辯論的"],"en":["open to discussion or argument; not clearly right or wrong"]}', NULL, 'debatable point / highly debatable / debatable issue', '[{"en":"Whether the new policy will succeed is highly debatable among economists.","zh-TW":"這項新政策是否會成功在經濟學家中頗有爭議。"},{"en":"It is debatable whether stricter regulations would benefit or harm businesses.","zh-TW":"更嚴格的法規是否會對企業有利或有害是值得辯論的。"}]', '{"adverb":"debatably","noun":"debate","verb":"debate"}', NULL, 3, 1823, NULL),
(1824, 'debatable issue', '/dɪˈbeɪtəbəl ˈɪʃuː/', 'noun', '{"zh-TW":["有爭議性的問題；引發辨論的議題"],"en":["a topic or question that is open to discussion, interpretation, or dispute"]}', NULL, 'address a debatable issue / explore a debatable issue / debatable issue in society', '[{"en":"The role of social media in democracy is a highly debatable issue.","zh-TW":"社交媒體在民主中的角色是一個高度具爭議性的問題。"},{"en":"The professor assigned a debatable issue for students to argue from both sides.","zh-TW":"教授分配了一個具爭議性的議題，要求學生從兩方面進行辨論。"}]', NULL, NULL, 5, 1824, NULL),
(1825, 'debate', '/dɪˈbeɪt/', 'noun / verb', '{"zh-TW":["辯論；討論"],"en":["a formal discussion on a particular topic"]}', '{"prefix":{"text":"de-","meaning":"down/thoroughly (徹底)"},"root":{"text":"bat","meaning":"beat (打)"},"logic":"徹底地交鋒辯駁，即「辯論」。"}', 'public/heated debate; heated debate / public debate / open to debate', '[{"en":"There was a heated debate about the new policy.","zh-TW":"關於新政策有一場激烈的辯論。"},{"en":"They debated the issue for hours.","zh-TW":"他們就這個問題辯論了幾個小時。"},{"en":"There is a heated debate about immigration policy.","zh-TW":"關於移民政策有激烈的辯論。"},{"en":"The issue is still open to debate.","zh-TW":"這個議題仍有討論空間。"}]', '{"noun":"debate","verb":"debate","adjective":"debatable"}', NULL, 2, 1825, NULL),
(1826, 'debate club', '/''dɪˈbeɪt klʌb/', 'noun', '{"zh-TW":["辯論社；辯論俱樂部"],"en":["a student organization focused on competitive debate and public speaking skills"]}', NULL, 'join a debate club / debate club competition / debate club activities', '[{"en":"She joined the debate club to improve her public speaking and argumentation skills.","zh-TW":"她加入了辯論社，以提高公開演講和論辯技能。"},{"en":"Debate club members compete in regional and national tournaments.","zh-TW":"辯論社成員參加地區和全國比賽。"}]', NULL, NULL, 4, 1826, NULL),
(1827, 'debenture', '/dɪˈbentʃər/', 'noun', '{"zh-TW":["債券；無擔保債券"],"en":["a type of loan bond not secured by specific assets"]}', NULL, 'issue a debenture / debenture holder / convertible debenture', '[{"en":"The company raised funds through a public debenture issue.","zh-TW":"公司通過公開發行債券籌集了資金。"},{"en":"Debenture holders receive fixed interest regardless of profitability.","zh-TW":"債券持有人無論盈虧都可獲得固定利息。"}]', '{"plural":"debentures","adjective":"debenture"}', NULL, 3, 1827, NULL),
(1828, 'debit', '/ˈdebɪt/', 'noun', '{"zh-TW":["借方；借記"],"en":["a record of money taken from an account; an accounting entry reducing assets"]}', NULL, 'debit card / debit account / debit entry / direct debit', '[{"en":"Each purchase was recorded as a debit in the ledger.","zh-TW":"每筆購買都在帳本上記錄為借方。"},{"en":"Set up a direct debit to pay bills automatically.","zh-TW":"設定直接借記以自動支付帳單。"}]', '{"verb":"debit","antonym":"credit"}', NULL, 2, 1828, NULL),
(1829, 'debit card', '/ˈdɛbɪt kɑːrd/', 'noun', '{"zh-TW":["簽帳金融卡；扣款卡"],"en":["a card that deducts money directly from a bank account"]}', NULL, 'pay with a debit card / debit card PIN', '[{"en":"He prefers to pay with a debit card to avoid debt.","zh-TW":"他偏好使用簽帳金融卡以避免負債。"},{"en":"Enter your PIN when paying by debit card.","zh-TW":"使用簽帳金融卡付款時請輸入您的密碼。"}]', NULL, NULL, 4, 1829, NULL),
(1830, 'debrief', '/ˌdiːˈbriːf/', 'verb', '{"zh-TW":["彙報；事後討論"],"en":["to question someone after a completed task or event"]}', NULL, 'debrief the team / post-event debrief', '[{"en":"The team met to debrief after the conference.","zh-TW":"團隊在會議後開會進行事後討論。"},{"en":"A thorough debrief helps identify lessons learned.","zh-TW":"徹底的彙報有助於識別所學到的經驗教訓。"}]', '{"noun":"debrief","adjective":"debriefed"}', NULL, 3, 1830, NULL),
(1831, 'debt', '/det/', 'noun', '{"zh-TW":["債務；欠款"],"en":["money that is owed to someone"]}', NULL, 'pay off/be in debt', '[{"en":"He is struggling to pay off his debts.","zh-TW":"他正努力償還債務。"},{"en":"The company is heavily in debt.","zh-TW":"這家公司負債累累。"}]', '{"noun":"debt/debtor"}', NULL, 1, 1831, NULL),
(1832, 'debt covenant', '/det ˈkʌvənənt/', 'noun', '{"zh-TW":["債務契約條款"],"en":["a condition in a loan agreement that the borrower must comply with"]}', NULL, 'comply with debt covenants / breach a debt covenant', '[{"en":"The company breached a debt covenant by failing to maintain its interest coverage ratio.","zh-TW":"公司因未能維持其利息覆蓋比率而違反了債務契約條款。"},{"en":"Debt covenants protect lenders by restricting risky borrower behavior.","zh-TW":"債務契約條款通過限制借款人的風險行為來保護貸款方。"}]', NULL, NULL, 5, 1832, NULL),
(1833, 'debt financing', '/det ˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["債務融資"],"en":["raising capital by borrowing money that must be repaid with interest"]}', NULL, 'use debt financing / debt financing strategy / debt financing vs equity', '[{"en":"Debt financing allows companies to raise capital without diluting ownership.","zh-TW":"債務融資允許公司在不稀釋所有權的情況下籌集資金。"},{"en":"High debt financing increases financial risk during downturns.","zh-TW":"高債務融資在經濟下滑期間增加了財務風險。"}]', NULL, NULL, 5, 1833, NULL),
(1834, 'debt forgiveness', '/det fəˈɡɪvnɪs/', 'noun', '{"zh-TW":["債務減免；債務豁免"],"en":["the cancellation of part or all of a borrower''s outstanding debt"]}', NULL, 'negotiate debt forgiveness / debt forgiveness program', '[{"en":"The government offered debt forgiveness to small businesses impacted by the crisis.","zh-TW":"政府為受危機影響的小型企業提供了債務減免。"},{"en":"Debt forgiveness may have tax implications for the recipient.","zh-TW":"對接受方而言，債務豁免可能有稅務影響。"}]', '{"synonym":"debt relief","verb":"forgive debt"}', NULL, 5, 1834, NULL),
(1835, 'debt ratio', '/det ˈreɪʃioʊ/', 'noun', '{"zh-TW":["負債比率"],"en":["total debt divided by total assets, measuring financial leverage"]}', NULL, 'calculate debt ratio / high debt ratio', '[{"en":"A debt ratio above 60% may concern lenders about repayment ability.","zh-TW":"60%以上的負債比率可能使貸款方對還款能力感到擔憂。"},{"en":"The company lowered its debt ratio by selling non-core assets.","zh-TW":"公司通過出售非核心資產降低了負債比率。"}]', NULL, NULL, 4, 1835, NULL),
(1836, 'debt restructuring', '/det riːˈstrʌktʃərɪŋ/', 'noun', '{"zh-TW":["債務重組"],"en":["modifying loan terms to give a borrower relief from financial difficulty"]}', NULL, 'pursue debt restructuring / complete debt restructuring', '[{"en":"The company entered debt restructuring negotiations with its creditors.","zh-TW":"公司與債權人進行了債務重組談判。"},{"en":"Debt restructuring extended repayment terms by five years.","zh-TW":"債務重組將還款期延長了五年。"}]', NULL, NULL, 5, 1836, NULL),
(1837, 'debt-to-equity ratio', '/det tə ˈekwɪti ˈreɪʃioʊ/', 'noun', '{"zh-TW":["負債股權比率；槓桿比率"],"en":["the ratio of a company''s total debt to its shareholders'' equity"]}', NULL, 'high debt-to-equity ratio / reduce debt-to-equity ratio', '[{"en":"A high debt-to-equity ratio may signal financial risk.","zh-TW":"高負債股權比率可能表示財務風險。"},{"en":"The firm reduced its debt-to-equity ratio through share issuance.","zh-TW":"公司通過發行股票降低了負債股權比率。"}]', NULL, NULL, 5, 1837, NULL),
(1838, 'debtor', '/ˈdetər/', 'noun', '{"zh-TW":["債務人；借款方"],"en":["a person or company that owes money to another"]}', NULL, 'trade debtor / debtor management / debtor collection', '[{"en":"The company''s debtors owed over two million in total.","zh-TW":"公司的債務人共欠款超過200萬元。"},{"en":"Debtor management software tracks outstanding invoices.","zh-TW":"債務人管理軟體追蹤未付發票。"}]', '{"opposite":"creditor"}', NULL, 2, 1838, NULL),
(1839, 'debug', '/diːˈbʌɡ/', 'verb', '{"zh-TW":["除錯"],"en":["to find and fix errors in computer code"]}', NULL, 'debug code / debug mode', '[{"en":"I spent hours debugging the code.","zh-TW":"我花了好幾個小時除錯。"},{"en":"Run it in debug mode.","zh-TW":"用除錯模式執行。"}]', '{"noun":"debugger","noun2":"debugging"}', NULL, 2, 1839, NULL),
(1840, 'decade', '/ˈdekeɪd/', 'noun', '{"zh-TW":["十年"],"en":["a period of ten years"]}', NULL, 'over the past decade', '[{"en":"The technology has evolved rapidly over the past decade.","zh-TW":"在過去十年中，技術迅速發展。"},{"en":"She spent a decade working overseas.","zh-TW":"她在海外工作了十年。"}]', '{"noun":"decade"}', NULL, 2, 1840, NULL),
(1841, 'decarbonization', '/ˌdiːˌkɑːrbənaɪˈzeɪʃən/', 'noun', '{"zh-TW":["脫碳；低碳化"],"en":["the reduction of carbon dioxide output associated with energy systems"]}', NULL, 'deep decarbonization / pathway to decarbonization / decarbonization strategy', '[{"en":"Decarbonization of the electricity sector is the first step in achieving net zero.","zh-TW":"電力部門的脫碳是實現淨零排放的第一步。"},{"en":"Corporate decarbonization plans are increasingly scrutinized by investors for credibility.","zh-TW":"企業的脫碳計劃越來越受到投資者的審視，以評估其可信度。"}]', '{"verb":"decarbonize","adjective":"decarbonized"}', NULL, 5, 1841, NULL),
(1842, 'decelerate', '/''diːˌseləˌreɪt/', 'verb', '{"zh-TW":["減速；放慢"],"en":["to reduce speed; to cause something to happen more slowly"]}', NULL, 'decelerate growth / decelerate the economy / start to decelerate', '[{"en":"After years of rapid expansion, the company''s growth began to decelerate.","zh-TW":"經過多年的快速擴張，公司的增長開始減速。"},{"en":"Rising interest rates caused the housing market to decelerate significantly.","zh-TW":"利率上升導致房地產市場顯著減速。"}]', '{"noun":"deceleration","adjective":"decelerated"}', NULL, 4, 1842, NULL),
(1843, 'decentralization', '/ˌdiːˌsentrəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["分散化；去中心化"],"en":["the process of distributing authority away from a central body"]}', NULL, 'political decentralization / fiscal decentralization / corporate decentralization', '[{"en":"Fiscal decentralization gives regional governments more control over budgets.","zh-TW":"財政分散化使地方政府對預算擁有更多控制權。"},{"en":"The decentralization of corporate decision-making empowered local managers.","zh-TW":"企業決策的分散化使本地管理人員獲得了更多授權。"}]', '{"verb":"decentralize","adjective":"decentralized"}', NULL, 5, 1843, NULL),
(1844, 'decide', '/dɪˈsaɪd/', 'verb', '{"zh-TW":["決定"],"en":["to make a choice after thinking"]}', NULL, 'decide on / decide to', '[{"en":"We decided to postpone the launch.","zh-TW":"我們決定延後發布。"},{"en":"Have you decided on a venue?","zh-TW":"你決定好場地了嗎？"}]', '{"verb":"decide","noun":"decision","adjective":"decisive","adverb":"decisively"}', NULL, 2, 1844, NULL),
(1845, 'decipher', '/dɪˈsaɪfər/', 'verb', '{"zh-TW":["解讀；破譯"],"en":["to convert a coded message into normal language; to interpret something complex"]}', NULL, 'decipher a code / decipher meaning / decipher the data', '[{"en":"Analysts try to decipher the signals from economic data.","zh-TW":"分析師試圖解讀來自經濟數據的訊號。"},{"en":"She struggled to decipher his handwritten notes.","zh-TW":"她費力地解讀他手寫的筆記。"}]', NULL, NULL, 3, 1845, NULL),
(1846, 'decision', 'dɪˈsɪʒən', 'noun', '{"zh-TW":["決定；決策","裁決"],"en":["a choice made after consideration","a judgment"]}', NULL, 'make a decision/final decision', '[{"en":"The final decision rests with management.","zh-TW":"最終決定由管理層做出。"}]', '{"verb":"decide","adjective":"decisive","adverb":"decisively"}', NULL, 3, 1846, 321),
(1847, 'decision tree', '/dɪˈsɪʒən triː/', 'noun', '{"zh-TW":["決策樹"],"en":["a diagram representing possible decision pathways and outcomes"]}', NULL, 'use a decision tree / build a decision tree', '[{"en":"A decision tree was used to evaluate risk across multiple scenarios.","zh-TW":"決策樹用於評估多個場景中的風險。"},{"en":"Decision trees help managers visualize complex choices.","zh-TW":"決策樹幫助管理者可視化複雜選擇。"}]', NULL, NULL, 5, 1847, NULL),
(1848, 'decision-maker', '/dɪˈsɪʒən ˈmeɪkər/', 'noun', '{"zh-TW":["決策者"],"en":["a person with the authority to make important decisions"]}', NULL, 'reach the decision-maker / senior decision-maker', '[{"en":"The sales team struggled to reach the key decision-maker.","zh-TW":"銷售團隊努力聯繫到關鍵決策者。"},{"en":"Always present proposals to the decision-maker directly.","zh-TW":"始終直接向決策者提交提案。"}]', NULL, NULL, 5, 1848, NULL),
(1849, 'decision-making framework', '/''dɪˌsɪʒən ˌmeɪkɪŋ ˌfreɪmwɜːrk/', 'noun', '{"zh-TW":["決策框架"],"en":["a structured approach or set of criteria used to guide the process of making decisions"]}', NULL, 'apply a decision-making framework / develop a decision-making framework / use a decision-making framework', '[{"en":"Using a decision-making framework helps ensure that all relevant factors are considered.","zh-TW":"使用決策框架有助於確保考慮所有相關因素。"},{"en":"The team adopted a shared decision-making framework to streamline the approval process.","zh-TW":"團隊採用了共享的決策框架，以簡化審批流程。"}]', '{"noun":"decision-making"}', NULL, 5, 1849, NULL);